import java.nio.file.Files;
import java.nio.file.InvalidPathException;
import java.nio.file.Path;

import org.eclipse.rdf4j.common.annotation.InternalUseOnly;

/** Resolves a configured WAL directory without allowing it to leave the NativeStore data directory. */
@InternalUseOnly
public final class WalDirectoryResolver {

	private WalDirectoryResolver() {
	}

	public static Path validateDirectoryName(String name) {
		try {
			Path path = Path.of(name);
			if (path.getRoot() != null) {
				throw new IllegalArgumentException("WAL directory name must be relative and unqualified: " + name);
			}
			for (Path component : path) {
				if ("..".equals(component.toString())) {
					throw new IllegalArgumentException("WAL directory name must not contain '..': " + name);
				}
			}
			return path;
		} catch (InvalidPathException e) {
			throw new IllegalArgumentException("Invalid WAL directory name: " + name, e);
		}
	}

	public static Path resolve(Path dataDirectory, String configuredName) throws IOException {
		String name = configuredName != null && !configuredName.isEmpty() ? configuredName
				: ValueStoreWalConfig.DEFAULT_DIRECTORY_NAME;
		Path relative = validateDirectoryName(name);
		Path realBase = dataDirectory.toRealPath();
		Path walDirectory = realBase.resolve(relative).normalize();
		if (walDirectory.equals(realBase) || !walDirectory.startsWith(realBase)) {
			throw new IOException("WAL directory must be inside the NativeStore data directory: " + name);
		}

		Path current = realBase;
		for (Path component : relative) {
			current = current.resolve(component);
			if (Files.isSymbolicLink(current) && !current.toRealPath().startsWith(realBase)) {
				throw new IOException("WAL directory resolves outside the NativeStore data directory: " + name);
			}
		}
		return dataDirectory.resolve(relative);
	}
}
